// `Env` is the ambient global interface generated by `wrangler types` (see
// worker-configuration.d.ts, gitignored — run `npm run types` after setting up
// wrangler.toml). We only need the token here, so narrow with Pick rather than
// hand-writing a separate binding type that can drift from the real config.
type CloudflareEnv = Pick<Env, "CLOUDFLARE_API_TOKEN">;

export function cfApiUrl(env: CloudflareEnv, path: string): string {
  return `https://api.cloudflare.com/client/v4${path}`;
}

const UPSTREAM_TIMEOUT_MS = 15000;

export async function cfApiFetch(
  env: CloudflareEnv,
  path: string,
  init: RequestInit = {},
): Promise<Response> {
  const headers = new Headers(init.headers);
  headers.set("Authorization", `Bearer ${env.CLOUDFLARE_API_TOKEN}`);
  if (init.body) headers.set("Content-Type", "application/json");
  return fetch(cfApiUrl(env, path), {
    ...init,
    headers,
    signal: init.signal ?? AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
  });
}
